#!/usr/bin/env python3

"""
Debug script to understand how package names are parsed
"""

import requirements


def debug_requirement_parsing():
    """Debug how requirement parsing works"""

    req_lines = [
        'yamllint',
        'ansible-lint', 
        'requests',
        'pyyaml',
        'ansible',
        'pytest'
    ]

    print("Parsing requirements:")
    for line in req_lines:
        try:
            reqs = list(requirements.parse(line))
            for req in reqs:
                print(f"  '{line}' -> name: '{req.name}', line: '{req.line}'")
        except Exception as e:
            print(f"  '{line}' -> ERROR: {e}")


if __name__ == "__main__":
    debug_requirement_parsing()
